import re

LEVELS = {"INFO", "ERROR", "WARN", "DEBUG"}


def extract_level(line: str) -> str | None:
    match = re.search(r"\b(ERROR|WARN|INFO|DEBUG)\b", line, flags=re.IGNORECASE)
    if not match:
        return None

    level = match.group(1).upper()
    return level if level in LEVELS else None


if __name__ == "__main__":
    print(extract_level("2026-09-25 12:00:03 ERROR Something failed"))
