import re


def parse_money(s: str) -> float | None:
    if not isinstance(s, str):
        return None

    cleaned = s.replace(",", "").replace("$", "")
    match = re.fullmatch(r"\d+(\.\d+)?|\.\d+", cleaned)
    if match is None:
        return None

    try:
        value = float(cleaned)
    except ValueError:
        return None

    return value
